#ifdef __CUDACC__
template <unsigned beMask>
template <typename Coop>
NCCL_DEVICE_INLINE void ncclGin_BackendMask<beMask>::waitSignal(Coop coop, ncclGinSignal_t signal, uint64_t least,
                                                                int bits, cuda::memory_order ord) const {
  coop.sync();
  if (coop.thread_rank() == 0) {
    auto sig = ncclGinCall<ncclGinApi_GetSignalPtr>(this->_makeCtx(), signal);
    (void)nccl::gin::internal::waitRollingLessEq</*EnableTimeout=*/false>(sig, least, bits, ord, this->comm.abortFlag,
                                                                          0ULL);
  }
  coop.sync();
}

template <unsigned beMask>
template <typename Coop>
NCCL_DEVICE_INLINE ncclResult_t ncclGin_BackendMask<beMask>::waitSignal(
  Coop coop, ncclGinSignal_t signal, uint64_t least, int bits, cuda::memory_order ord, uint64_t timeoutCycles) const {
  ncclResult_t ret = ncclSuccess;
  coop.sync();
  if (coop.thread_rank() == 0) {
    auto sig = ncclGinCall<ncclGinApi_GetSignalPtr>(this->_makeCtx(), signal);
    ret = nccl::gin::internal::waitRollingLessEq</*EnableTimeout=*/true>(sig, least, bits, ord, this->comm.abortFlag,
                                                                         timeoutCycles);
  }
  coop.sync();

    ncclDevCommRequirements_t reqs = NCCL_DEV_COMM_REQUIREMENTS_INITIALIZER;
    reqs.lsaMultimem = enable_lsa_multimem;
    if (get_env("EP_DISABLE_GIN", 0) == 0) {
        EP_HOST_ASSERT(
            (allow_hybrid_mode ? props.railedGinType : props.ginType) != NCCL_GIN_TYPE_NONE and
            "NCCL GIN is unavailable. This is usually due to a network configuration issue, "
            "such as `allow_hybrid_mode=0` (disable direct RDMA kernels) in multi-plane network.");
        EP_HOST_ASSERT(
            props.ginSupport[NCCL_GIN_TYPE_GDAKI] and
            "NCCL GDAKI is unavailable for this communicator.");

        gin_min_stride = props.ginMinStride;
        reqs.ginType = NCCL_GIN_TYPE_GDAKI;
        reqs.ginContextCount = num_allocated_qps;
        reqs.ginExclusiveContexts = true;
        reqs.ginQueueDepth = qp_depth > 0 ? qp_depth : kDefaultQPDepth;

        // Customized RDMA barrier needs extra signals
        reqs.ginSignalCount = num_ranks + 2 * 2;
        if (allow_hybrid_mode and num_rdma_storage_bytes > 0) {
            reqs.ginCustomStride = gin_min_stride;
            reqs.ginConnectionType = NCCL_GIN_CONNECTION_CUSTOM_STRIDE;
        } else {
            reqs.ginConnectionType = allow_hybrid_mode ? NCCL_GIN_CONNECTION_RAIL : NCCL_GIN_CONNECTION_FULL;
        }

        // SL index
        if (std::getenv("EP_DEFAULT_RDMA_SL") != nullptr)
            reqs.ginTrafficClass = get_env<int>("EP_DEFAULT_RDMA_SL");
        if (sl_idx.has_value())
            reqs.ginTrafficClass = sl_idx.value();
        if (std::getenv("EP_OVERRIDE_RDMA_SL") != nullptr)
            reqs.ginTrafficClass = get_env<int>("EP_OVERRIDE_RDMA_SL");
    }
#if NCCL_VERSION_CODE >= NCCL_VERSION(2, 31, 0)
    reqs.useRuntimeVersion = true;
    dev_comm.ptr = malloc(props.devCommRuntimeVersionSize);
#else
    EP_HOST_ASSERT(NCCL_VERSION_CODE == nccl_runtime_version and "Prior to NCCL 2.31, NCCL compile-time and runtime versions must be the same. Please re-compile DeepEP.");
    dev_comm.ptr = malloc(sizeof(ncclDevComm_t));
#endif
    EP_HOST_ASSERT(dev_comm.ptr != nullptr);
    NCCL_CHECK(ncclDevCommCreate(comm, &reqs, static_cast<ncclDevComm_t*>(dev_comm.ptr)));

void destroy_nccl_comm(const int64_t& nccl_comm) {
    NCCL_CHECK(ncclCommAbort(reinterpret_cast<ncclComm_t>(nccl_comm)));
    if (get_env<int>("EP_BUFFER_DEBUG"))
        printf("NCCL host communicator aborted\n");
}

template <typename coop_t = ncclCoopThread>
__device__ __forceinline__
void flush() const {
    gin.flush(coop_t());
}

template <typename team_t, typename coop_t = ncclCoopThread>
__device__ __forceinline__
void flush_async(const int& src_rank_idx, ncclGinRequest_t* request,
                 const int& extra_options = 0) const {
    IS_TEAM_WORLD_RAIL({
        gin.flushAsync(
            TEAM_WORLD_RAIL(),
            src_rank_idx,
            request,
            coop_t(),
            ncclGinOptFlagsDefault | extra_options
        );
    });
}

template <typename team_t, typename remote_action_t>
__device__ __forceinline__
void signal(const int& dst_rank_idx, const remote_action_t& remote_action) const {
    IS_TEAM_WORLD_RAIL({
        gin.signal(TEAM_WORLD_RAIL(), dst_rank_idx, remote_action);
    });
}

template <typename team_t, int64_t kNumTimeoutCycles>
__device__ __forceinline__
void wait_signal(const int& signal_idx, const int& rank_idx) const {
    IS_TEAM_WORLD_RAIL({
        // NOTES: signals are rolling counters, whose width follows the shadow counter type
        const auto shadow_ptr = gin.getSignalShadowPtr(signal_idx);
        const auto target = ++(*shadow_ptr);
        const auto result = gin.waitSignal(
            ncclCoopThread(), signal_idx, target, sizeof(*shadow_ptr) * 8,
            cuda::memory_order_acquire, kNumTimeoutCycles);
        if (result != ncclSuccess) {
            const auto signal = gin.readSignal(signal_idx, sizeof(*shadow_ptr) * 8, cuda::memory_order_acquire);
            // This waiting thread owns the shadow entry; reload only for diagnostics
            // to avoid keeping target live into the timeout path.
            const uint64_t timeout_target = *static_cast<const volatile uint64_t*>(shadow_ptr);
            printf("DeepEP Gin signal timeout, rank: %d, signal_idx: %d, signal: %lu, target: %lu\n",
                   rank_idx, signal_idx, signal, timeout_target);
            ptx::trap();
        }
    });
}

template <int64_t kNumTimeoutCycles, typename func_t>
__device__ __forceinline__ void timeout_while(const bool& condition, const func_t& func,
                                              int64_t start_clock = 0) {
    // User may share a start clock for multiple waits
    if (start_clock == 0)
        start_clock = clock64();

    while (condition) {
        const bool timeout = clock64() - start_clock >= kNumTimeoutCycles;
        if (func(timeout))
            break;

        if (timeout) {
            // Wait another 1 second to let all threads print information and trap
            start_clock = clock64();
            while (clock64() - start_clock < kNumOneSecCycles) {}
            ptx::trap();
        }

// During abort or any other cases, users might not call deregister API for
// symmetric window objects, we need to destroy all remaining window objects
// that are not deregistered by user to avoid memory leaks here.
CUDACHECKIGNORE(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
while (devr->winSortedCount > 0) {
  struct ncclDevrWindow* win = devr->winSorted[0].win;
  NCCLCHECKIGNORE(symWindowDestroy(comm, win->vidmem, stream), ret);
}
CUDACHECKIGNORE(cudaStreamSynchronize(stream));

NCCLCHECKIGNORE(symTeamDestroyAll(comm), ret);

// delete windowTable

/* Check gin status */
if (*asyncError == ncclSuccess && comm->sharedRes && comm->sharedRes->ginState.connected) {
  struct ncclGinState* ginState = &comm->sharedRes->ginState;
  // Gin progress thread status
  if (ginState->proxyThreadsCreated) {
    *asyncError = COMPILER_ATOMIC_LOAD(&comm->sharedRes->ginState.asyncResult, std::memory_order_acquire);
  }
  // Gin side errors, also works when we have no GIN progress thread.
  if (*asyncError == ncclSuccess) {
    bool ginError;
    NCCLCHECK(ncclGinQueryLastError(&comm->sharedRes->ginState, &ginError));
    if (ginError) {
      WARN("GIN Error detected");
      *asyncError = ncclRemoteError;
    }
  }
}
